            new SpellDef("avada_kedavra", "Avada Kedavra", "Авада Кедавра", "Killing Curse", "DRK", 6, "tree", "proj", "spirit", "L1", "flick", 60.0f, "Непростительное. Зелёный луч: мгновенная смерть не-босса с ОЗ ≤ 35% (мелких — ≤ 60%), иначе огромный урон; боссам — 15% текущих ОЗ. Стоит МС и 10% ваших ОЗ. +25 Тьмы.", "Ослепительный зелёный луч, вспышка, порыв ветра; цель падает беззвучно.", null, null, "цена ОЗ вдвое ниже", "при убийстве перезарядка −50%", "ray rng=40 dmg=3 exec=35 bosspct=15 hp=10 dark=25", "B,F,G"),
            new SpellDef("crucio", "Crucio", "Круцио", "Cruciatus Curse", "DRK", 6, "tree", "beam", "spirit", "L1", "strain", -1.0f, "Непростительное. Поддерживаемое (до 4 с): цель корчится, обездвижена, урон каждые 0.25 с. +15 Тьмы.", "Дрожащий воздух вместо луча, цель бьётся в судорогах, красноватые вспышки-нервы.", null, null, "боль перескакивает на соседа", "после — цель в ужасе бежит", "chan rng=20 max=4 dmg stun=0.4:writhe dark=15", "B,F,G"),
